@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#17202c;--muted:#75808a;--cream:#fffaf0;--gold:#ffcf77;--mint:#a8e3cf;--coral:#f59683;--night:#101524;--line:rgba(255,255,255,.16)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--night);font-family:'DM Sans',sans-serif;color:white}button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}.game-shell{position:relative;width:100vw;height:100dvh;min-height:420px;overflow:hidden;background:#d78c75;isolation:isolate;touch-action:none}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(18,24,39,.32),transparent 25%,transparent 65%,rgba(17,24,32,.16));z-index:1}.topbar{position:absolute;top:0;left:0;right:0;height:79px;padding:0 4.2%;display:flex;align-items:center;gap:26px;background:linear-gradient(180deg,rgba(20,25,40,.76),rgba(20,25,40,.08));z-index:3}.brand{display:flex;align-items:center;gap:9px;color:#fff;text-decoration:none;font:600 10px/1.1 'Space Grotesk';letter-spacing:1.9px}.brand b{font-weight:700}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(255,255,255,.48);border-radius:50%;font-size:20px;color:var(--gold)}.chapter{border-left:1px solid var(--line);padding-left:22px;display:grid;gap:2px}.chapter strong{font:500 13px 'Space Grotesk';letter-spacing:.1px}.eyebrow{font-size:9px;letter-spacing:1.7px;font-weight:700;color:rgba(255,255,255,.65)}.icon-btn{margin-left:auto;width:34px;height:34px;border-radius:50%;border:1px solid var(--line);background:rgba(19,27,42,.22);color:white;font-size:15px;display:grid;place-items:center;transition:.2s}.icon-btn+.icon-btn{margin-left:-17px}.icon-btn:hover{background:rgba(255,255,255,.18);transform:scale(1.05)}.mission-card{position:absolute;z-index:2;top:104px;left:4.2%;display:flex;align-items:center;gap:12px;padding:12px 14px;width:232px;border:1px solid rgba(255,255,255,.23);border-radius:12px;background:rgba(25,34,48,.57);backdrop-filter:blur(12px);box-shadow:0 9px 24px #17202c18}.mission-icon{font-size:19px;color:var(--gold)}.mission-card>div:nth-child(2){display:grid;gap:3px;flex:1}.mission-card strong{font:600 12px 'Space Grotesk'}.mission-card small{font-size:10px;color:rgba(255,255,255,.63)}.progress-ring{width:37px;height:37px;border:2px solid rgba(255,255,255,.22);border-top-color:var(--gold);border-right-color:var(--gold);border-radius:50%;display:grid;place-items:center;font-size:8px;font-weight:700;color:#fff;transform:rotate(0)}.character-card{position:absolute;z-index:2;top:104px;right:4.2%;display:flex;align-items:center;gap:11px;padding:10px 14px;border:1px solid rgba(255,255,255,.23);border-radius:12px;background:rgba(25,34,48,.57);backdrop-filter:blur(12px);min-width:217px}.avatar-mini{width:38px;height:38px;display:grid;place-items:center;background:linear-gradient(145deg,#f9c886,#e99181);color:#773f50;border-radius:12px;font-size:20px}.character-copy{display:grid;gap:3px}.character-copy>strong{font:600 12px 'Space Grotesk'}.character-copy>strong span{font:400 10px 'DM Sans';color:rgba(255,255,255,.72)}.trait-row{display:flex;gap:11px;font-size:9px;color:rgba(255,255,255,.67)}.trait-row b{color:#fff}.world-label{position:absolute;z-index:2;bottom:25px;left:4.2%;display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:1.5px;font-weight:700;color:rgba(255,255,255,.72);text-shadow:0 2px 6px #32333d}.live-dot{width:6px;height:6px;border-radius:50%;background:#a9e3cb;box-shadow:0 0 8px #a9e3cb}.label-divider{opacity:.45}.objective{position:absolute;z-index:2;bottom:21px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:9px 14px;border-radius:30px;background:rgba(20,27,41,.63);border:1px solid rgba(255,255,255,.19);backdrop-filter:blur(8px);font-size:11px;color:#fff;white-space:nowrap;transition:.2s}.objective-icon{color:var(--gold);font-size:15px}.objective kbd,.controls-hint kbd{font:600 9px 'DM Sans';padding:3px 6px;background:#ffffff24;border-radius:4px;color:#fff}.controls-hint{position:absolute;z-index:2;right:4.2%;bottom:27px;color:rgba(255,255,255,.72);font-size:8px;letter-spacing:1.4px;font-weight:700}.controls-hint kbd{margin-left:3px}.dialogue{position:absolute;z-index:6;left:50%;bottom:5%;transform:translateX(-50%);width:min(580px,calc(100% - 32px));padding:20px 24px 13px;background:rgba(25,32,43,.96);border:1px solid rgba(255,255,255,.19);border-radius:18px;box-shadow:0 24px 80px #1015218c;backdrop-filter:blur(18px);animation:rise .28s cubic-bezier(.2,.8,.2,1)}.hidden{display:none!important}@keyframes rise{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}.dialogue-top{display:flex;align-items:center;gap:12px;position:relative}.npc-portrait{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(140deg,#f7bd83,#ef8c81);font-size:24px;color:#673e51}.npc-heading{display:grid;gap:2px}.npc-heading .eyebrow{font-size:8px;color:#a8e3cf}.npc-heading strong{font:600 16px 'Space Grotesk'}.mood-line{font-size:10px;color:#a8aeb5}.close-dialog{position:absolute;right:0;top:0;width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,.17);background:#ffffff0b;font-size:20px;line-height:20px;color:#d4d7db}.bond-row{display:flex;align-items:center;gap:9px;margin:15px 0 12px;font-size:8px;font-weight:700;letter-spacing:1.1px;color:#aeb6bd}.bond-track{height:5px;flex:1;border-radius:4px;background:#ffffff1a;overflow:hidden}.bond-track i{height:100%;width:0;display:block;border-radius:4px;background:linear-gradient(90deg,#ffbd75,#a8e3cf);transition:width .5s ease}.bond-row b{font-size:9px;color:#fff;min-width:28px;text-align:right}.dialogue-text{margin:0 0 13px;font:400 13px/1.55 'DM Sans';color:#f3f0e9;min-height:40px}.response-label{display:flex;justify-content:space-between;margin-bottom:7px;font-size:8px;letter-spacing:1.4px;font-weight:700;color:#abb3ba}.response-label span{color:#a8e3cf}.choices{display:grid;grid-template-columns:1fr 1fr;gap:7px}.choice{position:relative;text-align:left;min-height:54px;padding:9px 11px 9px 38px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.045);border-radius:9px;transition:.18s}.choice:hover,.choice:focus-visible{background:rgba(168,227,207,.12);border-color:#a8e3cf80;transform:translateY(-1px);outline:none}.choice-icon{position:absolute;left:12px;top:12px;font-size:14px;color:var(--gold)}.choice strong{display:block;font:600 10px 'Space Grotesk';color:white}.choice small{display:block;margin-top:3px;font-size:9px;color:#a7afb6;line-height:1.25}.choice .trait-tag{position:absolute;right:8px;top:8px;color:#a8e3cf;font-size:7px;letter-spacing:.6px;text-transform:uppercase}.dialogue-footer{display:flex;justify-content:space-between;margin-top:11px;color:#818991;font-size:8px}.welcome-screen{position:absolute;inset:0;z-index:10;display:grid;grid-template-columns:1fr 1fr;background:#f8f2e7;color:var(--ink)}.welcome-art{position:relative;overflow:hidden;background:linear-gradient(158deg,#ecc09a 0%,#d99886 53%,#b57678 100%)}.welcome-art:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 55%,#f8f2e7 100%)}.welcome-sun{position:absolute;width:168px;height:168px;border-radius:50%;left:45%;top:24%;background:linear-gradient(145deg,#ffe6a9,#f2a67f);box-shadow:0 0 80px #ffdb9c75}.sun-orbit{position:absolute;border:1px solid #fff4d269;border-radius:50%;width:360px;height:360px;left:calc(45% - 96px);top:calc(24% - 96px)}.orbit-two{width:490px;height:490px;left:calc(45% - 161px);top:calc(24% - 161px)}.welcome-mountain{position:absolute;bottom:-1px;left:-4%;width:108%;height:44%;clip-path:polygon(0 60%,19% 23%,33% 48%,54% 3%,78% 51%,92% 18%,100% 42%,100% 100%,0 100%)}.mountain-back{background:#9e7583;opacity:.72;transform:translateY(-38px) scale(1.04)}.mountain-front{background:linear-gradient(140deg,#526a73,#334f5c);clip-path:polygon(0 35%,22% 55%,43% 17%,59% 39%,76% 10%,100% 47%,100% 100%,0 100%)}.welcome-caption{position:absolute;bottom:36px;left:8%;z-index:1;font:600 9px/1.65 'Space Grotesk';letter-spacing:2.5px;color:#fff8e9;opacity:.85}.welcome-star{position:absolute;z-index:1;color:#fff6d8}.star-one{left:25%;top:23%;font-size:21px}.star-two{left:70%;top:15%;font-size:17px}.welcome-copy{position:relative;z-index:2;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:50px 10% 48px 9%}.welcome-copy .eyebrow{color:#b17d72;font-size:9px}.welcome-copy h1{margin:15px 0 13px;font:600 clamp(34px,4vw,55px)/1.07 'Space Grotesk';letter-spacing:-2.3px}.welcome-copy h1 em,.ending-screen h2 em{font-family:Georgia,serif;font-weight:400;color:#be716d}.welcome-copy>p{max-width:390px;margin:0;color:#6b7074;font-size:14px;line-height:1.7}.welcome-traits{display:flex;gap:15px;margin:21px 0 26px;color:#9a706c;font-size:8px;letter-spacing:1.1px;font-weight:700}.primary-btn{display:flex;justify-content:space-between;align-items:center;min-width:214px;padding:14px 17px;border:none;border-radius:8px;background:#263f49;color:#fff;font:600 12px 'Space Grotesk';box-shadow:0 8px 18px #263f4926;transition:.2s}.primary-btn:hover{transform:translateY(-2px);background:#345561;box-shadow:0 11px 22px #263f4938}.primary-btn span{font-size:16px;color:#b8e4d1}.welcome-note{display:flex;gap:8px;align-items:center;margin-top:15px;font-size:10px;color:#92928c}.welcome-note span{font-size:13px}.touch-controls{display:none;position:absolute;z-index:4;bottom:62px;left:20px;right:20px;justify-content:space-between;align-items:flex-end;pointer-events:none}.move-pad{display:flex;gap:9px;pointer-events:auto}.touch-btn{border:1px solid #ffffff50;background:#1a293896;box-shadow:0 4px 14px #20233155;backdrop-filter:blur(8px);touch-action:none;user-select:none;display:grid;place-items:center}.move-pad .touch-btn{width:51px;height:51px;border-radius:17px;font-size:30px;padding-bottom:5px}.jump-touch,.talk-touch{pointer-events:auto;width:57px;height:57px;border-radius:50%;position:absolute;right:74px;bottom:0;color:#fff;grid-template-rows:1fr auto;padding:8px 0 7px}.jump-touch span,.talk-touch span{font-size:21px;line-height:20px}.jump-touch small,.talk-touch small{font-size:7px;letter-spacing:1px}.talk-touch{right:0;width:51px;height:51px;background:#c87e68c9}.touch-btn:active,.touch-btn.pressed{background:#c78d74d9;transform:scale(.94)}.toast{position:absolute;z-index:5;left:50%;top:50%;transform:translate(-50%,-50%);background:rgba(26,35,47,.87);border:1px solid #ffffff2b;padding:11px 16px;border-radius:30px;font-size:11px;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,-65%)}.ending-screen{position:absolute;z-index:9;inset:0;background:#f8f2e7;color:var(--ink);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px}.ending-icon{font-size:42px;color:#d88978;margin-bottom:14px}.ending-screen .eyebrow{color:#ac8175}.ending-screen h2{font:600 clamp(38px,6vw,62px)/1.04 'Space Grotesk';letter-spacing:-2px;margin:14px 0}.ending-screen>p{max-width:390px;color:#74797a;line-height:1.7;font-size:14px}.ending-stats{display:flex;gap:28px;margin:18px 0 25px;color:#777;font-size:10px}.ending-stats span{display:grid;gap:4px}.ending-stats b{font:600 20px 'Space Grotesk';color:#344e56}.help-modal{position:absolute;inset:0;z-index:12;display:grid;place-items:center;background:#101524a6;backdrop-filter:blur(5px);padding:20px}.help-card{position:relative;width:min(470px,100%);background:#f8f2e7;color:var(--ink);border-radius:16px;padding:29px 31px}.help-card>.eyebrow{color:#aa7a71}.help-card h2{font:600 28px 'Space Grotesk';margin:12px 0}.help-card p{color:#646c70;font-size:13px;line-height:1.7}.help-card p b{color:#344e56}.help-note{padding:11px 13px;border-left:2px solid #cb8c78;background:#f1e7db;color:#8e655e;font:italic 12px Georgia;margin:17px 0}.help-card>.primary-btn{min-width:130px;margin-top:18px}.help-card .close-dialog{color:#43505a;border-color:#263f4925}
@media(max-width:700px){.topbar{height:62px;padding:0 17px;gap:14px}.brand{font-size:8px;letter-spacing:1.3px}.brand-mark{height:30px;width:30px}.chapter{padding-left:13px}.chapter .eyebrow{font-size:7px}.chapter strong{font-size:10px}.icon-btn{width:30px;height:30px}.icon-btn+.icon-btn{margin-left:-8px}.mission-card{top:76px;left:14px;width:190px;padding:9px 10px;gap:9px}.mission-card strong{font-size:10px}.mission-card small{font-size:9px}.mission-icon{font-size:16px}.progress-ring{width:31px;height:31px;font-size:7px}.character-card{top:76px;right:14px;min-width:0;padding:8px 9px;gap:7px}.avatar-mini{width:32px;height:32px;font-size:17px}.character-copy .eyebrow{font-size:7px;letter-spacing:1px}.character-copy>strong{font-size:10px}.character-copy>strong span{display:none}.trait-row{font-size:8px;gap:6px}.world-label{left:15px;bottom:22px;font-size:8px}.objective{bottom:18px;padding:8px 12px;font-size:10px}.controls-hint{display:none}.touch-controls{display:flex}.welcome-screen{grid-template-columns:1fr;grid-template-rows:35% 65%;overflow:auto}.welcome-art:after{background:linear-gradient(180deg,transparent 65%,#f8f2e7 100%)}.welcome-sun{width:112px;height:112px;left:48%;top:14%}.sun-orbit{width:245px;height:245px;left:calc(48% - 66px);top:calc(14% - 66px)}.orbit-two{width:330px;height:330px;left:calc(48% - 108px);top:calc(14% - 108px)}.welcome-mountain{height:67%}.mountain-back{transform:translateY(-18px) scale(1.04)}.welcome-caption{display:none}.welcome-copy{justify-content:flex-start;padding:10px 8% 23px}.welcome-copy .eyebrow{font-size:8px}.welcome-copy h1{font-size:36px;margin:8px 0}.welcome-copy>p{font-size:12px;line-height:1.5;max-width:340px}.welcome-traits{margin:12px 0 15px;gap:12px;font-size:7px}.primary-btn{padding:12px 15px;min-width:200px}.welcome-note{margin-top:11px;font-size:9px}.dialogue{bottom:8px;padding:13px 15px 10px;border-radius:15px;width:calc(100% - 16px)}.dialogue-top{gap:9px}.npc-portrait{width:40px;height:40px;border-radius:12px;font-size:20px}.npc-heading strong{font-size:14px}.bond-row{margin:10px 0 8px}.dialogue-text{font-size:11px;line-height:1.45;min-height:32px;margin-bottom:9px}.response-label{font-size:7px;margin-bottom:5px}.choices{gap:5px}.choice{min-height:47px;padding:7px 8px 7px 31px}.choice-icon{left:9px;top:10px;font-size:12px}.choice strong{font-size:9px}.choice small{font-size:8px;margin-top:2px}.choice .trait-tag{font-size:6px;right:5px;top:5px}.dialogue-footer{font-size:7px;margin-top:8px}.touch-controls:has(~.dialogue:not(.hidden)){opacity:.22;pointer-events:none}.objective{bottom:79px}.world-label{bottom:30px}.help-card{padding:23px 22px}.help-card h2{font-size:24px}}
@media(max-height:650px) and (min-width:701px){.dialogue{bottom:2%;padding:14px 20px 9px}.bond-row{margin:9px 0}.dialogue-text{margin-bottom:8px;min-height:30px}.choice{min-height:48px}.welcome-copy{padding-top:30px;padding-bottom:30px}.welcome-copy h1{font-size:42px}.welcome-traits{margin:14px 0 18px}}
@media(max-width:380px){.character-card{right:8px}.mission-card{left:8px;width:177px}.character-copy .trait-row{gap:4px}.character-copy .trait-row span:last-child{display:none}.welcome-copy h1{font-size:32px}.welcome-copy>p{font-size:11px}.welcome-traits{gap:8px}.dialogue-footer span:last-child{display:none}}

(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {
    start: $('startBtn'), welcome: $('welcomeScreen'), dialogue: $('dialogue'), ending: $('endingScreen'),
    help: $('helpModal'), mission: $('missionProgress'), progress: $('progressText'), objective: $('objective'),
    npcName: $('npcName'), npcRole: $('npcRole'), npcMood: $('npcMood'), npcPortrait: $('npcPortrait'),
    bondFill: $('bondFill'), bondValue: $('bondValue'), dialogueText: $('dialogueText'), choices: $('choices'),
    turn: $('turnLabel'), toast: $('toast')
  };
  const npcData = [
    {id:'lena',name:'Lena',title:'THE GARDENER',symbol:'❀',x:620,color:'#ef987c',hair:'#654954',trait:'warm-hearted',mood:'Kind, but quietly worried',greeting:'I used to grow enough for everyone. Lately, everyone just takes their own little patch and goes home.',need:'to be appreciated',likes:'listen',agree:'“A shared garden,” she says, smiling. “I think the soil misses all those footsteps.”',resolved:false,trust:0,turns:0},
    {id:'bo',name:'Bo',title:'THE FERRY KEEPER',symbol:'◈',x:1260,color:'#8ca6aa',hair:'#3b4b55',trait:'prickly',mood:'Guarded, not unkind',greeting:'The ferry stays on my side. I built it, I mend it. Everyone else can walk around.',need:'to feel respected',likes:'promise',agree:'Bo takes a long breath. “All right. I can show you how to mend the other side. But you’re holding the hammer.”',resolved:false,trust:0,turns:0},
    {id:'sol',name:'Sol',title:'THE STORYKEEPER',symbol:'☼',x:1900,color:'#dca768',hair:'#6d5268',trait:'tender-hearted',mood:'A little low today',greeting:'People don’t sit for stories anymore. Maybe the old ones aren’t worth telling.',need:'a reason to hope',likes:'encourage',agree:'Sol’s eyes brighten. “Then tonight, I’ll tell the story of this very conversation.”',resolved:false,trust:0,turns:0}
  ];
  const actions = [
    {id:'listen',icon:'◉',title:'Listen closely',desc:'Give their feelings a little room',tag:'EMPATHY',key:'empathy'},
    {id:'share',icon:'✦',title:'Find a common thread',desc:'Share something honest of your own',tag:'CHARISMA',key:'charisma'},
    {id:'encourage',icon:'☼',title:'Offer some hope',desc:'Help them see what could be',tag:'OPTIMISM',key:'optimism'},
    {id:'promise',icon:'↗',title:'Make a small promise',desc:'Offer a real, doable next step',tag:'SINCERITY',key:'sincerity'}
  ];
  const player = {x:100,y:0,vx:0,vy:0,w:34,h:57,face:1,onGround:false,walk:0,air:0};
  const stats={charisma:3,empathy:4,optimism:3,sincerity:3};
  const world={started:false,finished:false,now:0,last:0,viewW:1000,viewH:650,scale:1,worldW:2200,camera:0,ground:0,active:null,agreements:0,turns:0,collected:0,toastTimer:0,keys:{left:false,right:false},jumpQueued:false,talkQueued:false,particles:[],sound:false};
  const platforms=[{x:345,w:145,height:92},{x:845,w:150,height:132},{x:1515,w:178,height:100}];
  const keepsakes=[{x:410,p:0,label:'A ribbon for the garden',taken:false},{x:915,p:1,label:'A ferry token',taken:false},{x:1580,p:2,label:'A page from an old story',taken:false}];
  const stars=Array.from({length:42},(_,i)=>({x:(i*173+87)%2300,y:55+(i*97)%230,r:.7+(i%3)*.35,phase:i*1.7}));
  function resize(){
    const w=window.innerWidth,h=window.innerHeight;
    world.scale=Math.min(w/1000,h/650); if(world.scale>1.18) world.scale=1.18;
    canvas.width=Math.round(w*devicePixelRatio);canvas.height=Math.round(h*devicePixelRatio);
    canvas.style.width=w+'px';canvas.style.height=h+'px';
    world.viewW=w/world.scale;world.viewH=h/world.scale;
    world.ground=world.viewH-100;
  }
  window.addEventListener('resize',resize);resize();
  const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');world.toastTimer=2.1;}
  function drawBackground(t){
    const w=world.viewW,h=world.viewH,g=world.ground;
    let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#556b86');grad.addColorStop(.4,'#b17f89');grad.addColorStop(.78,'#efbb96');grad.addColorStop(1,'#efc89f');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
    // dusky sun and its soft halo
    const sx=w*.68-world.camera*.045,sy=Math.min(h*.45,300);
    let halo=ctx.createRadialGradient(sx,sy,8,sx,sy,190);halo.addColorStop(0,'#ffe7b589');halo.addColorStop(1,'#ffd6a000');ctx.fillStyle=halo;ctx.fillRect(sx-200,sy-200,400,400);
    ctx.fillStyle='#ffe1a9';ctx.beginPath();ctx.arc(sx,sy,43,0,Math.PI*2);ctx.fill();
    // drifting clouds
    for(let i=0;i<5;i++){let x=((i*270-t*7-world.camera*.11)%(w+260)+w+260)%(w+260)-90,y=90+(i%3)*53;ctx.fillStyle=`rgba(255,235,215,${.09+i%2*.035})`;ctx.beginPath();ctx.ellipse(x,y,45,9,0,0,Math.PI*2);ctx.ellipse(x+25,y-5,24,12,0,0,Math.PI*2);ctx.ellipse(x+47,y+1,36,8,0,0,Math.PI*2);ctx.fill();}
    for(const s of stars){let x=s.x-world.camera*.08;if(x>-20&&x<w+20){ctx.globalAlpha=.12+.22*(.5+.5*Math.sin(t*1.7+s.phase));ctx.fillStyle='#fff4d8';ctx.beginPath();ctx.arc(x,s.y, s.r,0,Math.PI*2);ctx.fill();}}ctx.globalAlpha=1;
