243:     button.addEventListener('pointerdown',event=>{event.preventDefault();button.setPointerCapture(event.pointerId);if(key==='jump'){if(world.started&&!world.active)world.jumpQueued=true;}else world.keys[key]=true;});
244:     const release=event=>{if(key!=='jump')world.keys[key]=false;};
245:     button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);
246:   });
247:   addEventListener('keydown',event=>{
248:     const key=event.key.toLowerCase();
249:     if(['arrowleft','arrowright',' ','arrowup'].includes(key))event.preventDefault();
250:     if(key==='escape'){if(!ui.help.classList.contains('hidden'))ui.help.classList.add('hidden');else closeConversation();return;}
251:     if(!world.started||world.finished)return;
252:     if(key==='arrowleft'||key==='a')world.keys.left=true;
253:     if(key==='arrowright'||key==='d')world.keys.right=true;
254:     if(key===' '||key==='arrowup'||key==='w')world.jumpQueued=true;
255:     if(key==='e'||key==='enter'){if(world.active){const finish=ui.choices.querySelector('.choice');if(finish&&ui.choices.childElementCount===1)finish.click();}else world.talkQueued=true;}
256:   });
257:   addEventListener('keyup',event=>{const key=event.key.toLowerCase();if(key==='arrowleft'||key==='a')world.keys.left=false;if(key==='arrowright'||key==='d')world.keys.right=false;});
258:   document.addEventListener('visibilitychange',()=>{world.last=0;world.keys.left=false;world.keys.right=false;});
259:   syncHUD();updateObjective();
260:   function frame(ms){const t=ms/1000,dt=world.last?Math.min(.035,(ms-world.last)/1000):.016;world.last=ms;world.now=t;update(dt);drawWorld(t);requestAnimationFrame(frame);}requestAnimationFrame(frame);
261: })();

