@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#17202c;--muted:#75808a;--cream:#fffaf0;--gold:#ffcf77;--mint:#a8e3cf;--coral:#f59683;--night:#101524;--line:rgba(255,255,255,.16)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--night);font-family:'DM Sans',sans-serif;color:white}button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}.game-shell{position:relative;width:100vw;height:100dvh;min-height:420px;overflow:hidden;background:#d78c75;isolation:isolate;touch-action:none}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(18,24,39,.32),transparent 25%,transparent 65%,rgba(17,24,32,.16));z-index:1}.topbar{position:absolute;top:0;left:0;right:0;height:79px;padding:0 4.2%;display:flex;align-items:center;gap:26px;background:linear-gradient(180deg,rgba(20,25,40,.76),rgba(20,25,40,.08));z-index:3}.brand{display:flex;align-items:center;gap:9px;color:#fff;text-decoration:none;font:600 10px/1.1 'Space Grotesk';letter-spacing:1.9px}.brand b{font-weight:700}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(255,255,255,.48);border-radius:50%;font-size:20px;color:var(--gold)}.chapter{border-left:1px solid var(--line);padding-left:22px;display:grid;gap:2px}.chapter strong{font:500 13px 'Space Grotesk';letter-spacing:.1px}.eyebrow{font-size:9px;letter-spacing:1.7px;font-weight:700;color:rgba(255,255,255,.65)}.icon-btn{margin-left:auto;width:34px;height:34px;border-radius:50%;border:1px solid var(--line);background:rgba(19,27,42,.22);color:white;font-size:15px;display:grid;place-items:center;transition:.2s}.icon-btn+.icon-btn{margin-left:-17px}.icon-btn:hover{background:rgba(255,255,255,.18);transform:scale(1.05)}.mission-card,.character-card{position:absolute;z-index:2;top:104px;display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid rgba(255,255,255,.23);border-radius:12px;background:rgba(25,34,48,.57);backdrop-filter:blur(12px);box-shadow:0 9px 24px #17202c18}.mission-card{left:4.2%;width:232px}.mission-icon{font-size:19px;color:var(--gold)}.mission-card>div:nth-child(2){display:grid;gap:3px;flex:1}.mission-card strong{font:600 11px 'Space Grotesk'}.mission-card small{font-size:10px;color:#e3d8c6}.progress-ring{width:37px;height:37px;border:2px solid rgba(255,255,255,.22);border-radius:50%;display:grid;place-items:center;font-size:9px;font-weight:700}.character-card{right:4.2%;min-width:220px}.avatar-mini{width:39px;height:39px;display:grid;place-items:center;border-radius:12px;background:linear-gradient(140deg,#f7bd83,#ef8c81);font-size:21px;color:#673e51}.character-copy{display:grid;gap:3px}.character-copy>strong{font:600 12px 'Space Grotesk'}.character-copy>strong span{font:500 10px 'DM Sans';color:#d8dfe3}.trait-row{display:flex;gap:9px;font-size:9px;color:#d4dce0}.trait-row b{color:var(--gold)}.world-label{position:absolute;z-index:2;left:4.2%;bottom:28px;display:flex;align-items:center;gap:8px;color:#fff;text-shadow:0 1px 5px #18202b;font-size:9px;font-weight:700;letter-spacing:1.5px}.live-dot{width:6px;height:6px;border-radius:50%;background:#a8e3cf;box-shadow:0 0 9px #a8e3cf}.label-divider{color:rgba(255,255,255,.55)}.objective{position:absolute;z-index:2;left:50%;bottom:21px;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:10px 15px;border:1px solid rgba(255,255,255,.25);border-radius:99px;background:rgba(25,32,43,.73);backdrop-filter:blur(10px);box-shadow:0 8px 26px #17202c28;font-size:11px;white-space:nowrap}.objective-icon{color:var(--gold);font-size:14px}.objective kbd,.controls-hint kbd{padding:2px 5px;border:1px solid rgba(255,255,255,.32);border-radius:4px;background:rgba(255,255,255,.13);font:600 9px 'DM Sans'}.controls-hint{position:absolute;z-index:2;right:4.2%;bottom:29px;color:rgba(255,255,255,.83);font-size:8px;font-weight:700;letter-spacing:1px;text-shadow:0 1px 4px #17202c}.controls-hint kbd{margin-left:3px}.touch-controls{display:none}.toast{position:absolute;z-index:7;left:50%;top:86px;transform:translate(-50%,-10px);padding:10px 15px;border:1px solid rgba(255,255,255,.23);border-radius:10px;background:rgba(25,32,43,.88);color:white;font-size:12px;opacity:0;pointer-events:none;transition:.22s}.toast.show{opacity:1;transform:translate(-50%,0)}
.dialogue{position:absolute;z-index:6;left:50%;bottom:5%;transform:translateX(-50%);width:min(580px,calc(100% - 32px));max-height:88%;overflow:auto;padding:20px 24px 13px;background:rgba(25,32,43,.96);border:1px solid rgba(255,255,255,.19);border-radius:18px;box-shadow:0 24px 80px #1015218c;backdrop-filter:blur(18px);animation:rise .28s cubic-bezier(.2,.8,.2,1)}.hidden{display:none!important}@keyframes rise{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}.dialogue-top{display:flex;align-items:center;gap:12px;position:relative}.npc-portrait{width:48px;height:48px;flex:0 0 auto;border-radius:15px;display:grid;place-items:center;background:linear-gradient(140deg,#f7bd83,#ef8c81);font-size:24px;color:#673e51}.npc-heading{display:grid;gap:2px}.npc-heading .eyebrow{font-size:8px;color:#a8e3cf}.npc-heading strong{font:600 16px 'Space Grotesk'}.mood-line{font-size:11px;color:#b8c2ca}.close-dialog{margin-left:auto;width:32px;height:32px;border:1px solid rgba(255,255,255,.15);border-radius:50%;background:rgba(255,255,255,.07);font-size:21px;line-height:1}.bond-row{display:flex;align-items:center;gap:9px;margin:15px 0 11px;color:#aab5bf;font-size:8px;font-weight:700;letter-spacing:1px}.bond-track{height:6px;flex:1;overflow:hidden;border-radius:99px;background:rgba(255,255,255,.12)}.bond-track i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#f59683,#ffcf77);transition:width .35s}.bond-row b{color:var(--gold);font-size:10px}.dialogue-text{margin:0 0 13px;color:#fff6e8;font:500 14px/1.55 'Space Grotesk';min-height:42px}.response-label{display:flex;justify-content:space-between;margin-bottom:8px;color:#a8e3cf;font-size:8px;font-weight:700;letter-spacing:1.3px}.response-label span{color:#aab5bf}.choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.choice{position:relative;display:grid;grid-template-columns:25px 1fr;align-content:center;column-gap:8px;min-height:63px;padding:9px 11px;border:1px solid rgba(255,255,255,.12);border-radius:11px;background:rgba(255,255,255,.045);text-align:left;transition:.18s}.choice:hover,.choice:focus-visible{border-color:var(--gold);background:rgba(255,207,119,.09);outline:none;transform:translateY(-1px)}.choice-icon{grid-row:span 2;align-self:center;color:var(--gold);font-size:17px}.choice strong{font:600 11px 'Space Grotesk'}.choice small{margin-top:3px;color:#aeb9c4;font-size:9px;line-height:1.35}.choice .trait-tag{position:absolute;right:8px;top:7px;color:#a8e3cf;font-size:7px;font-weight:700;letter-spacing:.7px}.dialogue-footer{display:flex;justify-content:space-between;margin-top:11px;color:#8996a2;font-size:9px}
.welcome-screen{position:absolute;inset:0;z-index:10;display:grid;grid-template-columns:1fr 1fr;background:#f8f2e7;color:var(--ink)}.welcome-art{position:relative;overflow:hidden;background:linear-gradient(155deg,#df987e,#a45f69 58%,#594e69)}.welcome-art:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 58%,rgba(35,42,61,.19))}.welcome-sun{position:absolute;left:49%;top:23%;width:clamp(125px,18vw,220px);aspect-ratio:1;border-radius:50%;background:linear-gradient(135deg,#ffe5a7,#f8af83);box-shadow:0 0 80px #ffcf7780}.sun-orbit{position:absolute;left:calc(49% - 88px);top:calc(23% - 88px);width:clamp(300px,32vw,420px);aspect-ratio:1;border:1px solid #fff6d545;border-radius:50%}.orbit-two{left:calc(49% - 135px);top:calc(23% - 135px);width:clamp(390px,42vw,550px)}.welcome-mountain{position:absolute;bottom:-4%;left:-10%;width:120%;height:48%;clip-path:polygon(0 55%,13% 28%,24% 54%,40% 14%,58% 58%,72% 25%,100% 69%,100% 100%,0 100%)}.mountain-back{background:#836178;transform:translateY(-28px)}.mountain-front{background:linear-gradient(160deg,#56546b,#293b50);clip-path:polygon(0 45%,18% 24%,36% 58%,55% 18%,73% 52%,90% 30%,100% 48%,100% 100%,0 100%)}.welcome-caption{position:absolute;z-index:1;left:8%;bottom:9%;font:600 10px/1.6 'Space Grotesk';letter-spacing:2px;color:#fff8e9}.welcome-star{position:absolute;z-index:1;color:#ffdf9a}.star-one{top:18%;right:19%;font-size:22px}.star-two{top:42%;left:17%;font-size:16px}.welcome-copy{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:8% clamp(34px,8vw,120px);overflow:auto}.welcome-copy .eyebrow{color:#a16c63}.welcome-copy h1{margin:15px 0;font:600 clamp(38px,5vw,63px)/1.04 'Space Grotesk';letter-spacing:-2.7px}.welcome-copy h1 em,.ending-screen h2 em{font-weight:500;color:#bd766b}.welcome-copy>p{max-width:440px;margin:0;color:#58616b;font-size:15px;line-height:1.7}.welcome-traits{display:flex;flex-wrap:wrap;gap:17px;margin:24px 0 27px;color:#77808a;font-size:9px;font-weight:700;letter-spacing:1px}.welcome-traits span:first-child{color:#b67566}.primary-btn{display:inline-flex;align-items:center;justify-content:center;gap:16px;min-width:220px;padding:14px 19px;border:0;border-radius:9px;background:#263547;color:white;font:600 13px 'Space Grotesk';box-shadow:0 8px 20px #26354725;transition:.2s}.primary-btn:hover{transform:translateY(-2px);background:#344a60}.primary-btn span{font-size:17px;color:var(--gold)}.welcome-note{margin-top:16px;color:#92999f;font-size:10px}.welcome-note span{margin-right:5px}.ending-screen,.help-modal{position:absolute;inset:0;z-index:9;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;background:rgba(13,20,32,.83);backdrop-filter:blur(12px);text-align:center}.ending-screen{z-index:11}.ending-icon{margin-bottom:13px;color:var(--gold);font-size:38px}.ending-screen>.eyebrow{color:var(--mint)}.ending-screen h2,.help-card h2{margin:12px 0;font:600 clamp(34px,6vw,58px)/1.04 'Space Grotesk';letter-spacing:-1.6px}.ending-screen h2 em{color:var(--gold)}.ending-screen>p{max-width:410px;color:#cad2d9;font-size:13px;line-height:1.6}.ending-stats{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin:15px 0 24px}.ending-stats span{padding:9px 12px;border:1px solid var(--line);border-radius:9px;color:#c7d0d7;font-size:10px}.ending-stats b{color:var(--gold);font-size:13px}.help-modal{z-index:12;padding:18px}.help-card{position:relative;width:min(510px,100%);max-height:100%;overflow:auto;padding:32px;border:1px solid rgba(255,255,255,.19);border-radius:19px;background:#202b3b;text-align:left;box-shadow:0 25px 80px #0006}.help-card>.close-dialog{position:absolute;right:17px;top:17px}.help-card>.eyebrow{color:var(--mint)}.help-card h2{font-size:34px;letter-spacing:-1px}.help-card p{color:#c4cdd4;font-size:13px;line-height:1.65}.help-card p b{color:var(--gold)}.help-note{margin:17px 0;padding:12px 14px;border-left:2px solid var(--gold);background:rgba(255,207,119,.08);color:#e9dfcc;font-size:12px}.help-card .primary-btn{min-width:150px;padding:11px 16px}
.battle-screen{position:absolute;inset:0;z-index:8;display:flex;align-items:center;justify-content:center;padding:clamp(16px,4vh,40px);background:rgba(12,18,30,.72);backdrop-filter:blur(9px);overflow-y:auto;overscroll-behavior:contain}.battle-card{width:min(650px,100%);max-height:100%;overflow:auto;padding:clamp(20px,3vw,32px);border:1px solid rgba(255,255,255,.2);border-radius:24px;background:linear-gradient(145deg,rgba(37,49,66,.98),rgba(22,30,44,.98));box-shadow:0 28px 90px rgba(0,0,0,.4)}.battle-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.battle-heading .eyebrow{color:var(--mint)}.battle-heading h2{margin:5px 0 0;font:600 clamp(23px,4vw,32px)/1.1 'Space Grotesk',sans-serif}.battle-round{padding:8px 11px;border:1px solid rgba(255,255,255,.16);border-radius:99px;color:var(--gold);font-size:10px;font-weight:700;letter-spacing:1px;white-space:nowrap}.enemy-stage{display:flex;align-items:center;gap:19px;margin:22px 0 13px;padding:17px;border:1px solid rgba(255,255,255,.1);border-radius:17px;background:rgba(10,17,28,.32)}.enemy-sigil{flex:0 0 74px;height:74px;display:grid;place-items:center;border-radius:22px;background:radial-gradient(circle at 35% 30%,rgba(168,227,207,.4),rgba(111,153,155,.12) 67%);color:var(--mint);font-size:43px;text-shadow:0 0 24px rgba(168,227,207,.8);animation:enemyFloat 3s ease-in-out infinite}.enemy-copy{min-width:0;flex:1;display:grid;gap:5px}.enemy-copy strong{font:600 16px 'Space Grotesk',sans-serif}.enemy-copy>span{color:#c1cbd2;font-size:12px;line-height:1.4}.enemy-hp,.party-meter{height:7px;overflow:hidden;border-radius:99px;background:rgba(255,255,255,.12)}.enemy-hp i,.party-meter i{display:block;width:100%;height:100%;border-radius:inherit;background:linear-gradient(90deg,#f59683,#ffcf77);transition:width .3s ease}.enemy-copy small{color:#aab5bf;font-size:10px}.battle-log{min-height:40px;margin:12px 0;padding:11px 13px;border-left:2px solid var(--gold);border-radius:0 9px 9px 0;background:rgba(255,207,119,.08);color:#f6ead3;font-size:12px;line-height:1.5}.party-lineup{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.party-member{display:flex;align-items:center;gap:9px;min-width:0;padding:10px;border:1px solid rgba(255,255,255,.11);border-radius:13px;background:rgba(255,255,255,.045);transition:border-color .2s,background .2s,opacity .2s}.party-member.active{border-color:rgba(168,227,207,.75);background:rgba(168,227,207,.12)}.party-member.down{opacity:.42}.party-icon{font-size:23px}.party-info{display:grid;gap:5px;flex:1;min-width:0}.party-info strong{display:flex;flex-direction:column;gap:1px;font:600 11px 'Space Grotesk',sans-serif}.party-info strong small{color:#aeb9c4;font:500 9px 'DM Sans',sans-serif}.party-info>small{color:#c3ccd4;font-size:9px;white-space:nowrap}.party-meter{height:5px}.party-meter i{background:linear-gradient(90deg,#8bd2b7,#c4edc9)}.battle-command-label{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:19px 0 9px}.battle-command-label span{font:600 13px 'Space Grotesk',sans-serif}.battle-command-label small{color:#97a3af;font-size:10px}.battle-commands{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.battle-command{display:grid;justify-items:start;gap:4px;min-height:83px;padding:12px;border:1px solid rgba(255,255,255,.14);border-radius:13px;background:rgba(255,255,255,.055);text-align:left;transition:transform .18s,border-color .18s,background .18s}.battle-command:hover,.battle-command:focus-visible{transform:translateY(-2px);border-color:var(--gold);background:rgba(255,207,119,.1);outline:none}.battle-command>span{color:var(--gold);font-size:18px}.battle-command strong{font:600 12px 'Space Grotesk',sans-serif}.battle-command small{color:#aeb9c4;font-size:10px;line-height:1.35}.battle-continue{width:100%;margin-top:15px;padding:13px 16px;border:0;border-radius:12px;background:var(--mint);color:#17202c;font-weight:700;transition:filter .2s,transform .2s}.battle-continue: