  const w=world.viewW,h=world.viewH,g=world.ground;let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#556b86');grad.addColorStop(.4,'#b17f89');grad.addColorStop(.78,'#efbb96');grad.addColorStop(1,'#efc89f');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
  const sx=w*.68-world.camera*.045,sy=Math.min(h*.45,300);let halo=ctx.createRadialGradient(sx,sy,8,sx,sy,190);halo.addColorStop(0,'#ffe7b589');halo.addColorStop(1,'#ffd6a000');ctx.fillStyle=halo;ctx.fillRect(sx-200,sy-200,400,400);ctx.fillStyle='#ffe1a9';ctx.beginPath();ctx.arc(sx,sy,43,0,Math.PI*2);ctx.fill();
  for(let i=0;i<5;i++){let x=((i*270-t*7-world.camera*.11)%(w+260)+w+260)%(w+260)-90,y=90+(i%3)*53;ctx.fillStyle=`rgba(255,235,215,${.09+i%2*.035})`;ctx.beginPath();ctx.ellipse(x,y,45,9,0,0,Math.PI*2);ctx.ellipse(x+25,y-5,24,12,0,0,Math.PI*2);ctx.ellipse(x+47,y+1,36,8,0,0,Math.PI*2);ctx.fill();}
  for(const s of stars){let x=s.x-world.camera*.08;if(x>-20&&x<w+20){ctx.globalAlpha=.12+.22*(.5+.5*Math.sin(t*1.7+s.phase));ctx.fillStyle='#fff4d8';ctx.beginPath();ctx.arc(x,s.y,s.r,0,Math.PI*2);ctx.fill();}}ctx.globalAlpha=1;
  drawHillLayer(g-95,'#997783',.16,150,44);drawHillLayer(g-42,'#6d777c',.29,230,54);
  for(let i=0;i<9;i++){let x=i*315-world.camera*.42;if(x < -120||x> w+80)continue;let y=g-42-(i%3)*7;ctx.fillStyle=i%2?'#657477':'#73777a';ctx.fillRect(x,y-48,48,48);ctx.beginPath();ctx.moveTo(x-9,y-48);ctx.lineTo(x+24,y-74);ctx.lineTo(x+57,y-48);ctx.fill();ctx.fillStyle='#dca68c66';ctx.fillRect(x+10,y-27,9,14);ctx.fillRect(x+29,y-27,9,14);}
  ctx.fillStyle='#344d4e';ctx.fillRect(0,g,w,h-g);ctx.fillStyle='#71835f';ctx.fillRect(0,g,w,8);ctx.fillStyle='#9f986b';ctx.fillRect(0,g+8,w,4);ctx.fillStyle='#405657';for(let x=-((world.camera*.35)%60);x<w+80;x+=60){ctx.fillRect(x,g+16,31,2);ctx.fillRect(x+29,g+28,20,2);}
  ctx.fillStyle='#d2a27e';ctx.globalAlpha=.52;ctx.beginPath();ctx.moveTo(w*.44,g);ctx.bezierCurveTo(w*.48,g-75,w*.56,g-45,w*.6,g-3);ctx.lineTo(w*.68,g);ctx.fill();ctx.globalAlpha=1;
}
function drawHillLayer(base,color,parallax,step,amp){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,world.viewH);for(let x=0;x<=world.viewW+step;x+=step){const wx=x+world.camera*parallax;let y=base+Math.sin(wx*.006)*amp+Math.sin(wx*.014)*amp*.34;ctx.lineTo(x,y);}ctx.lineTo(world.viewW,world.viewH);ctx.closePath();ctx.fill();}
function drawProps(){const g=world.ground;for(let i=0;i<52;i++){let wx=(i*127+45)%world.worldW,x=wx-world.camera;if(x<-35||x>world.viewW+35)continue;let y=g-2-(i%4)*2;ctx.strokeStyle=i%3?'#a1a46e':'#d99c87';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x-4,y-8,x-2,y-14-i%5);ctx.moveTo(x,y);ctx.quadraticCurveTo(x+5,y-7,x+7,y-11);ctx.stroke();if(i%3===0){ctx.fillStyle='#f6d2a0';ctx.beginPath();ctx.arc(x-2,y-14-i%5,2,0,Math.PI*2);ctx.fill();}}
  for(const xw of [220,1040,1700]){let x=xw-world.camera;if(x<-40||x>world.viewW+40)continue;ctx.fillStyle='#5e5657';ctx.fillRect(x,g-44,5,44);ctx.fillStyle='#a9a078';ctx.fillRect(x-13,g-43,32,14);ctx.font='8px DM Sans';ctx.fillStyle='#fff2d6';ctx.fillText(xw===220?'GARDEN':xw===1040?'FERRY':'STORIES',x-11,g-33);}
}

